/*
 * The tune engine: the startup sound, the fault beep and the critical-battery
 * tune. No task of its own: TomTask (tom_dac_output.c) asks for a tune with
 * tune_player_request() and, while one plays, fills each 4 ms half of its
 * speaker buffer with tune_player_render(). The rules (one tune plays and
 * one waits, priorities, fixed 50 % amplitude, 5 ms fades) are in
 * tune_player.h.
 *
 * Main steps:
 *   1. tune_player_request(): start the tune now, queue it, or ignore it
 *   2. tune_player_render(), per sample: tp_note_sample() (a sine times the
 *      fade envelope); at the end of a note tp_load_note() loads the next
 *      one; after the last note tp_finish() lets the queued tune take over
 *   3. tune_player_stop(): silence at once
 * Tests: Tests/TunePlayer/test_tune_player.c.
 */
#include "tune_player.h"

#include <math.h>
#include <stddef.h>

#define TP_TWO_PI   6.2831853071795864769f

/* Entries of a note table, as the uint8_t that tune_t.count holds. */
#define TP_NOTE_COUNT(table)  ((uint8_t)(sizeof(table) / sizeof((table)[0])))

/* ------------------------------------------------------------------------- */
/* The tunes (const: they live in flash, not in RAM)                          */
/* ------------------------------------------------------------------------- */

/* Rising C major arpeggio, played once when TomTask starts. */
static const tune_note_t s_startup_notes[] =
{
    {  523U, 120U },    /* C5 */
    {  659U, 120U },    /* E5 */
    {  784U, 120U },    /* G5 */
    { 1047U, 260U },    /* C6, held */
};

/* Descending G-E-C with short rests between the notes: critical battery. */
static const tune_note_t s_critical_notes[] =
{
    { 784U, 160U },     /* G5 */
    {   0U,  20U },     /* rest */
    { 659U, 160U },     /* E5 */
    {   0U,  20U },     /* rest */
    { 523U, 160U },     /* C5 */
};

/* The old 200 ms 1 kHz fault beep, now a one-note tune. */
static const tune_note_t s_fault_notes[] =
{
    { 1000U, 200U },
};

const tune_t g_tune_startup  = { s_startup_notes,  TP_NOTE_COUNT(s_startup_notes),  TUNE_PRIORITY_NORMAL };
const tune_t g_tune_critical = { s_critical_notes, TP_NOTE_COUNT(s_critical_notes), TUNE_PRIORITY_CRITICAL };
const tune_t g_tune_fault    = { s_fault_notes,    TP_NOTE_COUNT(s_fault_notes),    TUNE_PRIORITY_FAULT };

/* ------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* ------------------------------------------------------------------------- */

/** Convert milliseconds to frames; the 64-bit product cannot overflow. */
static uint32_t tp_ms_to_frames(uint32_t ms, uint32_t fs_hz)
{
    return (uint32_t)(((uint64_t)ms * (uint64_t)fs_hz) / 1000U);
}

/**
 * @brief Load note p->note of the current tune: frame count, fade length and
 *        phase step, with the phase reset to 0. A note too short to last one
 *        frame is skipped.
 * @return 1 when a note was loaded, 0 when the tune has no notes left.
 */
static uint8_t tp_load_note(tune_player_t *p)
{
    while (p->note < p->current->count)
    {
        const tune_note_t *nt = &p->current->notes[p->note];
        const uint32_t frames = tp_ms_to_frames(nt->duration_ms, p->fs_hz);
        if (frames > 0U)
        {
            uint32_t fade = tp_ms_to_frames(TUNE_FADE_MS, p->fs_hz);
            if (fade > frames / 2U)
            {
                fade = frames / 2U;     /* short note: fade in for one half, out for the other */
            }
            p->frame = 0U;
            p->note_frames = frames;
            p->fade_frames = fade;
            p->phase = 0.0f;
            p->phase_inc = TP_TWO_PI * (float)nt->freq_hz / (float)p->fs_hz;
            return 1U;
        }
        p->note++;
    }
    return 0U;
}

/** Make t the current tune from its first note. @return 0 if t has nothing to play. */
static uint8_t tp_start(tune_player_t *p, const tune_t *t)
{
    p->current = t;
    p->note = 0U;
    if (tp_load_note(p) == 0U)
    {
        p->current = NULL;
        return 0U;
    }
    return 1U;
}

/** The current tune has played its last note: the queued tune (if any) takes over. */
static void tp_finish(tune_player_t *p)
{
    const tune_t *next = p->pending;

    p->pending = NULL;
    p->current = NULL;
    if (next != NULL)
    {
        (void)tp_start(p, next);
    }
}

/**
 * @brief One sample of the current note, then advance the phase.
 *
 * The envelope rises linearly from 0 over the first fade_frames and falls
 * linearly to 0 over the last fade_frames, so the note starts and ends at 0.
 * Envelope <= 1 and |sin| <= 1, so |sample| <= TUNE_AMPLITUDE.
 */
static int16_t tp_note_sample(tune_player_t *p)
{
    const tune_note_t *nt = &p->current->notes[p->note];
    const uint32_t k = p->frame;
    float envelope = 1.0f;

    if (nt->freq_hz == 0U)
    {
        return 0;                               /* a rest */
    }

    if (k < p->fade_frames)
    {
        envelope = (float)k / (float)p->fade_frames;
    }
    else if (k >= p->note_frames - p->fade_frames)
    {
        envelope = (float)(p->note_frames - 1U - k) / (float)p->fade_frames;
    }

    const float value = (float)TUNE_AMPLITUDE * envelope * sinf(p->phase);
    p->phase += p->phase_inc;
    if (p->phase >= TP_TWO_PI)
    {
        p->phase -= TP_TWO_PI;
    }
    return (int16_t)value;
}

/* ------------------------------------------------------------------------- */
/* Public API                                                                 */
/* ------------------------------------------------------------------------- */

/**
 * @brief Initialise an idle player.
 * @param p Player state. NULL is safely ignored.
 * @param fs_hz Output sample rate.
 */
void tune_player_init(tune_player_t *p, uint32_t fs_hz)
{
    if (p == NULL)
    {
        return;
    }
    p->fs_hz = fs_hz;
    tune_player_stop(p);
}

/**
 * @brief Start a tune now, queue it, or ignore it (queue rule in tune_player.h).
 * @param p Player state.
 * @param t Tune to play.
 * @return 1 when playing or queued, 0 when ignored or dropped.
 */
uint8_t tune_player_request(tune_player_t *p, const tune_t *t)
{
    if ((p == NULL) || (tune_duration_ms(t) == 0U))
    {
        return 0U;                              /* nothing to play */
    }
    if (p->current == NULL)
    {
        return tp_start(p, t);                  /* idle: start now */
    }
    if ((t == p->current) || (t == p->pending))
    {
        return 0U;                              /* already playing or queued */
    }
    if ((p->pending == NULL) || (t->priority >= p->pending->priority))
    {
        p->pending = t;                         /* plays when the current tune ends */
        return 1U;
    }
    return 0U;                                  /* a more important tune is already queued */
}

/**
 * @brief Clear the current and the queued tune.
 * @param p Player state. NULL is safely ignored.
 */
void tune_player_stop(tune_player_t *p)
{
    if (p == NULL)
    {
        return;
    }
    p->current = NULL;
    p->pending = NULL;
    p->note = 0U;
    p->frame = 0U;
    p->note_frames = 0U;
    p->fade_frames = 0U;
    p->phase = 0.0f;
    p->phase_inc = 0.0f;
}

/**
 * @brief Report whether a tune is playing or queued.
 * @param p Player state.
 * @return 1 while playing or queued, else 0.
 */
uint8_t tune_player_busy(const tune_player_t *p)
{
    if (p == NULL)
    {
        return 0U;
    }
    return ((p->current != NULL) || (p->pending != NULL)) ? 1U : 0U;
}

/**
 * @brief Read the tune being played.
 * @param p Player state.
 * @return The current tune, or NULL when idle.
 */
const tune_t *tune_player_current(const tune_player_t *p)
{
    return (p != NULL) ? p->current : NULL;
}

/**
 * @brief Render n mono samples; silence once the tune has ended.
 * @param p Player state.
 * @param mono Output buffer.
 * @param n Number of samples.
 * @return Samples that belonged to a tune.
 */
uint32_t tune_player_render(tune_player_t *p, int16_t *mono, uint32_t n)
{
    uint32_t i = 0U;

    if (mono == NULL)
    {
        return 0U;
    }

    if (p != NULL)
    {
        while ((i < n) && (p->current != NULL))
        {
            mono[i] = tp_note_sample(p);
            i++;
            p->frame++;
            if (p->frame >= p->note_frames)
            {
                p->note++;
                if (tp_load_note(p) == 0U)
                {
                    /* Last note done. A queued tune becomes current now and
                     * starts with the next call; the rest of this buffer is
                     * silence. */
                    tp_finish(p);
                    break;
                }
            }
        }
    }

    const uint32_t produced = i;
    for (; i < n; i++)
    {
        mono[i] = 0;
    }
    return produced;
}

/**
 * @brief Total length of a tune, rests included.
 * @param t Tune.
 * @return Sum of the note durations in ms (0 for NULL / no notes).
 */
uint32_t tune_duration_ms(const tune_t *t)
{
    uint32_t total = 0U;

    if ((t == NULL) || (t->notes == NULL))
    {
        return 0U;
    }
    for (uint8_t i = 0U; i < t->count; i++)
    {
        total += t->notes[i].duration_ms;
    }
    return total;
}
